<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { cambiarEstadoTrabajadorConcepto, guardarAsignacionConceptos, guardarTrabajadorConcepto, listarOpcionesTrabajadores, listarTrabajadorConceptos } from '../services/trabajadorConceptos'
import type { TrabajadorConceptoConfig, TrabajadorConceptoOption, TrabajadorConceptoPayload, TrabajadorOption } from '../interfaces/trabajadorConceptos.interface'
const trabajadores=ref<TrabajadorOption[]>([]),trabajadorId=ref<number|null>(null),trabajador=ref<TrabajadorOption|null>(null),conceptos=ref<TrabajadorConceptoOption[]>([]),configs=ref<TrabajadorConceptoConfig[]>([]),selectedIds=ref<number[]>([]),criterio=ref(''),estadoFiltro=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null);const defaults:TrabajadorConceptoPayload={datos_persona_id:0,concepto_id:0,aplica:true,monto_manual:null,fecha_inicio:null,fecha_fin:null,observacion:null,estado:true};const form=reactive<TrabajadorConceptoPayload>({...defaults});const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.';const configByConcept=computed(()=>new Map(configs.value.map(x=>[x.concepto_id,x])));const filtered=computed(()=>{const q=criterio.value.trim().toLocaleLowerCase();return conceptos.value.filter(x=>!q||`${x.codigo} ${x.descripcion}`.toLocaleLowerCase().includes(q))})
async function loadOptions(){try{trabajadores.value=(await listarOpcionesTrabajadores()).trabajadores}catch(v){error.value=message(v)}}
async function load(){if(trabajadorId.value===null){trabajador.value=null;conceptos.value=[];configs.value=[];selectedIds.value=[];return}loading.value=true;error.value='';try{const r=await listarTrabajadorConceptos(trabajadorId.value,estadoFiltro.value);trabajador.value=r.trabajador;conceptos.value=r.conceptos;configs.value=r.configuraciones;selectedIds.value=r.configuraciones.filter(x=>x.estado).map(x=>x.concepto_id)}catch(v){error.value=message(v)}finally{loading.value=false}}
async function saveAssignment(){if(trabajadorId.value===null)return;saving.value=true;error.value='';try{await guardarAsignacionConceptos(trabajadorId.value,selectedIds.value);success.value='Asignación de conceptos actualizada correctamente.';await load()}catch(v){error.value=message(v)}finally{saving.value=false}}
function openDetail(concepto:TrabajadorConceptoOption){const x=configByConcept.value.get(concepto.id);editing.value=x?.id??null;Object.assign(form,x?{datos_persona_id:x.datos_persona_id,concepto_id:x.concepto_id,aplica:x.aplica,monto_manual:x.monto_manual===null?null:Number(x.monto_manual),fecha_inicio:x.fecha_inicio,fecha_fin:x.fecha_fin,observacion:x.observacion,estado:x.estado}:{...defaults,datos_persona_id:trabajadorId.value??0,concepto_id:concepto.id});error.value='';modal.value=true}
function validate(){if(!form.datos_persona_id||!form.concepto_id)return 'Debe seleccionar trabajador y concepto.';if(form.monto_manual!==null&&(!Number.isFinite(form.monto_manual)||form.monto_manual<0||form.monto_manual>999999999999.999999))return 'El monto manual no es válido.';if(form.fecha_inicio&&form.fecha_fin&&form.fecha_fin<form.fecha_inicio)return 'La fecha fin debe ser mayor o igual a la fecha inicio.';if((form.observacion??'').length>500)return 'La observación admite como máximo 500 caracteres.';return ''}
async function saveDetail(){const issue=validate();if(issue)return void(error.value=issue);saving.value=true;error.value='';try{await guardarTrabajadorConcepto(editing.value,{...form,observacion:form.observacion?.trim()||null});modal.value=false;success.value=`Configuración ${editing.value?'actualizada':'registrada'} correctamente.`;await load()}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(x:TrabajadorConceptoConfig){const action=x.estado?'desactivar':'activar';if(!confirm(`¿Desea ${action} esta configuración?`))return;try{const r=await cambiarEstadoTrabajadorConcepto(x.id);x.estado=r.estado;success.value=r.message??`Configuración ${x.estado?'activada':'desactivada'} correctamente.`}catch(v){error.value=message(v)}}
const formatDate=(v:string|null)=>v?new Date(`${v}T00:00:00`).toLocaleDateString('es-PE'):'Sin fecha';onMounted(()=>loadOptions())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Recursos Humanos / Conceptos por trabajador</nav><header class="hero"><div class="mark">CT</div><div><small>MIA · RECURSOS HUMANOS · MAESTROS</small><h1>Conceptos por trabajador</h1><p>Asignaciones, excepciones, montos manuales y vigencias individuales.</p></div><strong>{{selectedIds.length}} asignados</strong></header><aside class="selector"><label>Trabajador de planilla<select v-model="trabajadorId" @change="load"><option :value="null">Seleccione un trabajador</option><option v-for="x in trabajadores" :key="x.id" :value="x.id">{{x.codigo_trabajador}} · {{x.nombre_completo}}</option></select></label><div v-if="trabajador"><b>{{trabajador.nombre_completo}}</b><span>Régimen: {{trabajador.regimen?.descripcion??trabajador.regimen_id}}</span></div></aside><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><template v-if="trabajador"><section class="filters"><label>Buscar concepto<input v-model.trim="criterio" placeholder="Código o descripción"></label><label>Configuración<select v-model="estadoFiltro" @change="load"><option value="">Todas</option><option value="1">Activas</option><option value="0">Inactivas</option></select></label><button :disabled="saving" @click="saveAssignment">{{saving?'Guardando…':'Guardar asignación'}}</button></section><section class="table-card"><header><small>RÉGIMEN COMPATIBLE</small><h2>Conceptos disponibles</h2></header><div v-if="loading" class="empty">Consultando conceptos…</div><div v-else-if="!filtered.length" class="empty">No hay conceptos compatibles con el régimen.</div><div v-else class="scroll"><table><thead><tr><th>Asignar</th><th>Concepto</th><th>Régimen</th><th>Aplica</th><th>Monto manual</th><th>Vigencia</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.id"><td><input v-model="selectedIds" type="checkbox" :value="x.id"></td><td><b>{{x.codigo}}</b><small>{{x.descripcion}}</small></td><td>{{x.regimen?.descripcion??'TODOS'}}</td><td>{{configByConcept.get(x.id)?.aplica===false?'No':'Sí'}}</td><td>{{configByConcept.get(x.id)?.monto_manual==null?'—':Number(configByConcept.get(x.id)?.monto_manual).toFixed(6)}}</td><td><template v-if="configByConcept.get(x.id)">{{formatDate(configByConcept.get(x.id)?.fecha_inicio??null)}}<br>{{formatDate(configByConcept.get(x.id)?.fecha_fin??null)}}</template><span v-else>—</span></td><td><span v-if="configByConcept.get(x.id)" :class="configByConcept.get(x.id)?.estado?'active':'inactive'">{{configByConcept.get(x.id)?.estado?'Activo':'Inactivo'}}</span><span v-else>Sin configurar</span></td><td class="actions"><button class="edit" @click="openDetail(x)">Configurar</button><button v-if="configByConcept.get(x.id)" :class="configByConcept.get(x.id)?.estado?'disable':'enable'" @click="toggle(configByConcept.get(x.id)!)">{{configByConcept.get(x.id)?.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div></section></template><section v-else class="empty welcome">Seleccione un trabajador para consultar los conceptos habilitados según su régimen.</section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="saveDetail"><header><div class="mark">CT</div><div><small>CONFIGURACIÓN INDIVIDUAL</small><h2>Detalle del concepto</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Aplica *<select v-model="form.aplica"><option :value="true">Sí</option><option :value="false">No, excluir</option></select></label><label>Monto manual<input v-model.number="form.monto_manual" type="number" min="0" step="0.000001"></label><label>Fecha inicio<input v-model="form.fecha_inicio" type="date"></label><label>Fecha fin<input v-model="form.fecha_fin" type="date"></label><label>Estado<select v-model="form.estado"><option :value="true">Activo</option><option :value="false">Inactivo</option></select></label><label class="full">Observación<textarea v-model="form.observacion" maxlength="500" rows="3"></textarea><small>{{form.observacion?.length??0}} / 500</small></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar detalle'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#7652a8;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.6rem;font-weight:800}.hero small,.table-card small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero strong{margin-left:auto;padding:6px 9px;border-radius:12px;color:var(--accent);background:#f2edfa;font-size:.52rem}.selector{margin-top:10px;padding:13px;display:flex;align-items:end;gap:15px;border-radius:9px;background:#fff}.selector label{width:min(580px,100%);font-size:.52rem}.selector div b,.selector div span{display:block;font-size:.52rem}.selector div span{color:#7e8a90}.selector select,.filters input,.filters select,.dialog input,.dialog select,.dialog textarea{width:100%;box-sizing:border-box;margin-top:4px;padding:8px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.54rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:10px;padding:12px;display:flex;align-items:end;gap:6px;border-radius:9px;background:#fff}.filters label{min-width:180px;font-size:.5rem}.filters label:first-child{margin-right:auto}.filters button,.dialog button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.table-card{margin-top:10px;border-radius:10px;background:#fff;overflow:hidden}.table-card>header{padding:13px 15px;border-bottom:1px solid #e7ebed}.table-card h2{margin:2px 0;font-size:.78rem}.scroll{overflow:auto}table{width:100%;min-width:1000px;border-collapse:collapse;font-size:.5rem}th,td{padding:9px;border-bottom:1px solid #e8ecee;text-align:left}th{color:#fff;background:#5b6e8e}td>b,td>small{display:block}.active,.inactive{display:inline-block;padding:4px 7px;border-radius:10px;font-size:.42rem}.active{color:#287154;background:#e6f7ee}.inactive{color:#9d4046;background:#fdebed}.actions{display:flex;gap:5px}.actions button{padding:6px 8px;border:0;border-radius:5px;font-size:.46rem}.edit{color:#79500b;background:#ffe7bd}.disable{color:#9d4046;background:#fdebed}.enable{color:#287154;background:#e6f7ee}.empty{padding:45px;text-align:center;font-size:.6rem}.welcome{margin-top:10px;border-radius:10px;background:#fff}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(760px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex;align-items:center;gap:9px}.dialog h2{margin:2px 0 12px;font-size:.9rem}.dialog>header>button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.dialog label{display:grid;margin-top:8px;font-size:.5rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.full{grid-column:1/-1}.dialog label small{margin-top:4px;color:#7e8a90}.dialog>footer{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}.soft{color:#64727a!important;background:#edf1f3!important}@media(max-width:800px){.hero,.filters,.selector{flex-wrap:wrap}.hero strong{margin-left:0}.filters label{width:100%}.grid{grid-template-columns:1fr}.full{grid-column:auto}.actions{min-width:150px}}
